<!-- wp:mbn-theme/section-location-heading-list-image {"heading":"What Compensation Can You Get for Your Damages in an Arizona Personal Injury Case?","introParagraphs":["While it’s true that financial compensation doesn’t undo an injury, it can support access to the best medical care and minimize financial concerns throughout the recovery process. In many cases, it also helps the injured person and their family achieve a sense of justice.","Civil law in Arizona recognizes two types of damages: economic and non-economic. In many cases, non-economic damages can be even more harmful than the economic ones associated with an accident. Examples of both types of damages include the following:"],"listItems":[{"title":"","description":"Medical expenses and future expenses related to medical care","label":"","url":"","id":"mr1cw9gv82nx7hnd8ha"},{"title":"","description":"Lost earnings from missed work and estimated future lost earnings for ongoing treatment or procedures","label":"","url":"","id":"mr1cw9gvrlpsshanv4"},{"title":"","description":"Reduced potential for future earnings in the case of a disabling accident","label":"","url":"","id":"mr1cw9gvq5rpoafznv"},{"id":"mr1cxgkz9sxc6700dkm","title":"","description":"Pain and suffering","label":"","url":""},{"id":"mr222k9vnm2sv66h9r","title":"","description":"Emotional anguish and loss of enjoyment of life","label":"","url":""},{"id":"mr222qp36v1q7ou3u87","title":"","description":"Scarring or disfigurement","label":"","url":""}],"imageUrl":"http://hastingsandhastings.dev.local/wp-content/uploads/2026/07/img-liocation-injury-legal-service.jpg","imageId":11217,"footerParagraphs":[]} /-->

